RDER BY time_ DESC) AS rn FROM camunda.act_hi_detail oplogclaimend WHERE oplogclaimend.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimend.name_ = ''userActivity'' AND cast(oplogclaimend.text_ as jsonb)->> ''action'' = ''Claim'' AND cast(text_ as jsonb)->> ''id'' in (SELECT end_stage_id FROM EndStage WHERE rn = 1) ), TransactionData AS ( SELECT Txn.proc_inst_id_, cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) AS transaction_json FROM camunda.act_hi_varinst Txn LEFT JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND Txn.name_ = ''Transaction'' AND Txn.var_type_ = ''json'' ) SELECT TicketID.ticketid AS \\"Case ID\\", pinst.case_creation_time AS \\"Case creation time\\", Alert.text_ AS \\"Alert\\", TransactionData.transaction_json -> ''observations'' -> ''payerVPA'' ->> ''externalId'' AS \\"Payer\\", TransactionData.transaction_json -> ''observations'' -> ''payeeVPA'' ->> ''externalId'' AS \\"Payee\\", CASE WHEN jsonb_typeof(TransactionData.transaction_json) = ''array'' THEN TransactionData.transaction_json -> 0 -> ''observations'' -> ''vpa'' ->> ''vcexternaladdressid'' ELSE TransactionData.transaction_json -> ''observations'' -> ''vpa'' ->> ''vcexternaladdressid'' END AS \\"VPA\\", CASE WHEN jsonb_typeof(TransactionData.transaction_json) = ''array'' THEN TransactionData.transaction_json -> 0 -> ''observations'' -> ''account'' ->> ''vcexternalaccountid'' ELSE TransactionData.transaction_json -> ''observations'' -> ''account'' ->> ''vcexternalaccountid'' END AS \\"Account\\", Amount.double_ / 100 AS \\"Amount\\", OplogClaimStart.start_time AS \\"Start stage\\", OplogClaimEnd.end_time AS \\"End stage\\", CASE WHEN OplogClaimEnd.end_time IS NULL OR OplogClaimStart.start_time IS NULL OR OplogClaimEnd.end_time < OplogClaimStart.start_time THEN ''NA'' ELSE EXTRACT(DAY FROM (OplogClaimEnd.end_time - OplogClaimStart.start_time))::TEXT || '' days '' 