    ((SELECT current_max + 2 FROM max_param_id), 'StartStage', 'JsonPath', 171, 0,12, NULL),
    ((SELECT current_max + 3 FROM max_param_id), 'EndStage', 'JsonPath', 171, 1,12, NULL),
    ((SELECT current_max + 4 FROM max_param_id), 'DateRange', 'DateRange', 171, NULL,12, NULL),
    ((SELECT current_max + 5 FROM max_param_id), 'Basis', 'JsonPath', 171, 2,12, NULL),
