E rn = 1) ), OplogClaimEnd AS ( SELECT oplogclaimend.proc_inst_id_, oplogclaimend.time_ AS end_time, ROW_NUMBER() OVER (PARTITION BY json_extract_scalar(oplogclaimend.text_, ''$.id'') ORDER BY time_ DESC) AS rn FROM t12refined.camunda.act_hi_detail oplogclaimend WHERE oplogclaimend.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimend.name_ = ''userActivity'' AND json_extract_scalar(oplogclaimend.text_, ''$.action'') = ''Claim'' AND json_extract_scalar(oplogclaimend.text_, ''$.id'') IN (SELECT end_stage_id FROM EndStage WHERE rn = 1) ), TransactionData AS ( SELECT Txn.proc_inst_id_, json_parse(from_utf8(Txnorg.bytes_)) AS transaction_json FROM t12refined.camunda.act_hi_varinst Txn LEFT JOIN t12refined.camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND Txn.name_ = ''Transaction'' AND Txn.var_type_ = ''json'' ) SELECT TicketID.ticketid AS \\"Case ID\\", pinst.case_creation_time AS \\"Case creation time\\", Alert.text_ AS \\"Alert\\", json_extract_scalar(TransactionData.transaction_json, ''$.observations.payerVPA.externalId'') AS \\"Payer\\", json_extract_scalar(TransactionData.transaction_json, ''$.observations.payeeVPA.externalId'') AS \\"Payee\\", CASE WHEN typeof(TransactionData.transaction_json) = ''array'' THEN json_extract_scalar(json_array_get(TransactionData.transaction_json, 0), ''$.observations.vpa.vcexternaladdressid'') ELSE json_extract_scalar(TransactionData.transaction_json, ''$.observations.vpa.vcexternaladdressid'') END AS \\"VPA\\", CASE WHEN typeof(TransactionData.transaction_json) = ''array'' THEN json_extract_scalar(json_array_get(TransactionData.transaction_json, 0), ''$.observations.account.vcexternalaccountid'') ELSE json_extract_scalar(TransactionData.transaction_json, ''$.observations.account.vcexternalaccountid'') END AS \\"Account\\", Amount.double_ / 100 AS \\"Amount\\", OplogClaimStart.start_time AS \\"Start stage\\", OplogClaimEnd.end_time AS \\"End stage\\", CASE WHEN OplogClaimEnd.end_time IS NULL OR OplogClaimStart.start_time IS NULL OR OplogClaimEnd.end_time < OplogClaimStart.start_time THEN ''NA'' ELSE format(''%s days %02d:%02d:%02d'', date_diff(''day'', OplogClaimStart.start_time, OplogClaimEnd.end_time), hour(OplogClaimEnd.end_time - OplogClaimStart.start_time), minute(OplogClaimEnd.end_time - OplogClaimStart.start_time), second(OplogClaimEnd.end_time - OplogClaimStart.start_time)) END AS \\"Total time taken\\", assigneeuser.vcemailid AS \\"Closed By\\", pinst.closed_on AS \\"Closed On\\" FROM ProcessInstances pinst LEFT JOIN LatestTask task ON task.proc_inst_id_ = pinst.proc_inst_id_ AND task.rn = 1 LEFT JOIN StartStage startstage ON startstage.proc_inst_id_ = pinst.proc_inst_id_ AND startstage.rn = 1 LEFT JOIN EndStage endstage ON endstage.proc_inst_id_ = pinst.proc_inst_id_ AND endstage.rn = 1 LEFT JOIN postgresql.ui.ticketidgenerator TicketID ON TicketID.processinstanceid = pinst.proc_inst_id_ LEFT JOIN t12refined.camunda.act_hi_varinst Alert ON Alert.proc_inst_id_ = pinst.proc_inst_id_ AND Alert.name_ = ''Alert'' AND Alert.var_type_ = ''string'' LEFT JOIN t12refined.camunda.act_hi_varinst Amount ON Amount.proc_inst_id_ = pinst.proc_inst_id_ AND Amount.name_ = ''TransactionAmount'' AND Amount.var_type_ = ''double'' LEFT JOIN OplogClaimStart ON OplogClaimStart.proc_inst_id_ = pinst.proc_inst_id_ AND OplogClaimStart.rn = 1 LEFT JOIN OplogClaimEnd ON OplogClaimEnd.proc_inst_id_ = pinst.proc_inst_id_ AND OplogClaimEnd.rn = 1 LEFT JOIN TransactionData ON TransactionData.proc_inst_id_ = pinst.proc_inst_id_ LEFT JOIN postgresql.ui.webuser assigneeuser ON assigneeuser.iuserid = CAST(task.assignee_ AS INTEGER)"
    },
